mod solution;

fn main() {
    let cases = [
    (r#"a=[1,3,7,0,0,0] m=3; b=[2,5,6]"#, r#"1,2,3,5,6,7"#),
    (r#"a=[2,0] m=1; b=[1]"#, r#"1,2"#),
    (r#"
a=[2,0] m=1; b=[1]
"#, r#"1,2"#),
    (r#"  
a=[1,3,7,0,0,0] m=3; b=[2,5,6]
  "#, r#"1,2,3,5,6,7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS in-place-merge");
}
